  @protected
  void sse_encode_outgoing(Outgoing self, SseSerializer serializer) {
    // Codec=Sse (Serialization based), see doc to use other codecs
    switch (self) {
      case Outgoing_Progress(
        done: final done,
        total: final total,
        speed: final speed,
        peak: final peak,
        eta: final eta,
        streams: final streams,
      ):
        sse_encode_i_32(0, serializer);
